import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.BzWmN0d8.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"lograil","text":"Universal logging for Web, Node.js & Electron","tagline":"High-performance, structured logging with a layered Core → Pipeline → Transport architecture that runs unchanged on Web, Node.js and Electron — and extends to other platforms through plugins.","actions":[{"theme":"brand","text":"Get Started","link":"/guide/getting-started"},{"theme":"alt","text":"API Reference","link":"/api/"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/axetroy/lograil"}]},"features":[{"title":"Runtime agnostic","details":"One API for Web, Node.js and Electron. The runtime adapter is auto-detected, or you can pass your own."},{"title":"Structured by default","details":"Every entry is a typed LogEntry with timestamp, scope, context, metadata and full Error cause chains."},{"title":"Pluggable pipeline","details":"Filters, processors and formatters compose freely. Redaction and sampling ship out of the box."},{"title":"First-class runtimes","details":"Web, Node.js and Electron are supported out of the box with auto-detected adapters — one API, no per-platform code."},{"title":"Extensible via plugins","details":"Plugins add transports, reshape the pipeline, intercept entries and register other plugins at runtime. Bring your own runtime adapter to support any other platform."},{"title":"Tiny & typed","details":"Written in TypeScript, ESM + CJS dual build, MIT licensed, with subpath exports for tree-shaking."},{"title":"Per-transport routing","details":"Each transport can set its own level and formatter, so one logger fans out — e.g. errors to OTLP, everything to a file."},{"title":"Observability built in","details":"Ship logs to an OpenTelemetry Collector via OTLP with traceId/spanId correlation, plus child loggers and sampling for cost control."},{"title":"Crash-safe","details":"Flush on exit, capture uncaught errors as fatal, and bridge console.* into the structured pipeline."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788629526000}'),i={name:"index.md"};function n(l,e,s,d,g,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="project-resources" tabindex="-1">Project resources <a class="header-anchor" href="#project-resources" aria-label="Permalink to &quot;Project resources&quot;">​</a></h2><ul><li><strong>Contributing</strong> — setup, test/lint gates and conventions: <a href="https://github.com/axetroy/lograil/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a></li><li><strong>Security</strong> — how to report vulnerabilities privately: <a href="https://github.com/axetroy/lograil/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a></li><li><strong>Changelog</strong> — generated from git history on each release: <a href="https://github.com/axetroy/lograil/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a></li><li><strong>Migrating</strong> from <code>electron-log</code> / <code>winston</code> / <code>pino</code>: <a href="/lograil/guide/migrating">guide</a></li><li><strong>Troubleshooting &amp; FAQ</strong>: <a href="/lograil/guide/troubleshooting">guide</a></li></ul>',2)])])}const h=t(i,[["render",n]]);export{p as __pageData,h as default};
